dict(id="monotonic-stack", title="Monotonic stack", cat="DSA", lvl=2,
 aka=["Monotonic stack", "Next greater / smaller", "Next greater or smaller element, histogram areas"],
 why="Solves next-greater, stock span and largest-rectangle problems in O(n). A common Medium/Hard step-up.",
 core=["Keep a stack whose values are always increasing (or decreasing). When a new element breaks the order, pop: each popped element has just found its next greater (or smaller) element.",
       "Every element is pushed and popped once, so the total is O(n). Store indices, not values, so you can compute distances and widths."],
 points=["Largest rectangle in histogram: previous and next smaller", "Daily temperatures: next greater, answer = index distance", "Sum of subarray minimums: count contributions with previous/next smaller"],
 code="vector<int> nge(n, -1); stack<int> st;\nfor (int i = 0; i < n; i++) {\n    while (!st.empty() && a[st.top()] < a[i]) { nge[st.top()] = a[i]; st.pop(); }\n    st.push(i);\n}",
 pit=["Strict vs non-strict comparison with duplicates (double counting)"],
 ask=["Largest rectangle in a histogram.", "Trapping rain water with a stack."],
 prac=[LC("daily-temperatures"), LC("largest-rectangle-in-histogram"), LC("sum-of-subarray-minimums")], learn=[TUF], rel=["stack-queue"]),

