dict(id="trees", title="Binary trees", cat="DSA", lvl=2,
 aka=["Binary trees", "trees", "Tree: any \"path\" or \"height\" question", "trees (traversals, BST, LCA)"],
 why="The largest single topic in interviews. Step 13–14 of the sheet.",
 core=["Traversals: preorder, inorder, postorder (DFS) and level order (BFS with a queue). Know both recursive and iterative versions.",
       "Most tree problems are 'return something from each subtree and combine': height, diameter, balanced check, max path sum. Write a function that returns the subtree answer and updates a global best.",
       "Lowest common ancestor: if both sides return non-null, the current node is the LCA."],
 points=["Diameter = max over nodes of leftHeight + rightHeight", "Serialize with preorder + null markers", "Views (left/right/top/bottom) use BFS with column index"],
 code="int best = INT_MIN;\nint gain(TreeNode* r) {\n    if (!r) return 0;\n    int L = max(0, gain(r->left)), R = max(0, gain(r->right));\n    best = max(best, r->val + L + R);\n    return r->val + max(L, R);\n}",
 pit=["Confusing 'path through node' with 'path returned to parent'", "Recursion depth on skewed trees"],
 ask=["Maximum path sum.", "Serialize and deserialize a tree.", "Lowest common ancestor."],
 prac=[LC("binary-tree-maximum-path-sum"), LC("lowest-common-ancestor-of-a-binary-tree"), LC("serialize-and-deserialize-binary-tree"), LC("diameter-of-binary-tree")], learn=[TUF], rel=["bst", "tree-dp", "bfs"]),

