dict(id="bfs", title="BFS and graph basics", cat="DSA", lvl=1,
 aka=["BFS", "Shortest path, unweighted", "graphs (BFS/DFS, topo, Dijkstra)", "graphs (BFS/DFS"],
 why="Graphs are in almost every product-company loop. BFS gives shortest paths when every edge costs the same.",
 core=["Store a graph as an adjacency list: vector<vector<int>> adj(n). Grids are implicit graphs with 4 neighbours.",
       "BFS uses a queue and visits nodes in order of distance from the source, so the first time you reach a node is its shortest path. O(V + E).",
       "Multi-source BFS starts with all sources in the queue (rotting oranges, nearest 0). 0-1 BFS uses a deque for edges of weight 0 or 1."],
 points=["Mark visited when pushing, not when popping", "Grid: dr/dc arrays for directions", "Bipartite check = BFS 2-colouring"],
 code="vector<int> dist(n, -1); queue<int> q; dist[s] = 0; q.push(s);\nwhile (!q.empty()) {\n    int u = q.front(); q.pop();\n    for (int v : adj[u]) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }\n}",
 pit=["Marking visited on pop → duplicates in queue"],
 ask=["Rotting oranges.", "Word ladder.", "Is the graph bipartite?"],
 prac=[LC("rotting-oranges"), LC("word-ladder"), LC("is-graph-bipartite"), LC("number-of-islands")], learn=[TUF, CSES], rel=["dfs", "dijkstra", "topo-sort"]),

